using System;using System.IO;using System.Linq;using System.Net;using System.Net.Http;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Text;using LcPack;
class PostGameTests {
 static int count;static void Check(bool b,string n){if(!b)throw new Exception(n);Console.WriteLine("PASS "+(++count)+" "+n);}
 class Downloads:HttpMessageHandler{public Manifest manifest;public byte[] bytes;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c){return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){RequestMessage=r,Content=r.RequestUri.AbsolutePath.EndsWith("manifest.json")?(HttpContent)new StringContent(Data.Json(manifest)):new ByteArrayContent(bytes)});}}
 static void Main(string[] args){try{Engine.CheckGameStopped();string root=Path.Combine(Path.GetTempPath(),"lgp-postgame-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"Lethal Company_Data/Managed"));foreach(string file in new[]{"Lethal Company.exe","UnityPlayer.dll","Lethal Company_Data/Managed/Assembly-CSharp.dll"})File.WriteAllText(Path.Combine(root,file),"fixture");string target=Path.Combine(root,Channel.ClientName);File.Copy(args[0],target);string oldHash=Data.Hash(target),newHash=Data.Hash(typeof(SelfUpdate).Assembly.Location);Check(AssemblyName.GetAssemblyName(target).Version<new Version("1.14.0.0"),"real old stable launcher fixture");
 var locked=new FileStream(target,FileMode.Open,FileAccess.Read,FileShare.Read);var migration=SelfUpdate.RefreshLegacyLauncher(root);Thread.Sleep(350);Check(!migration.IsCompleted,"migration waits for locked legacy parent without replacing it");locked.Dispose();migration.GetAwaiter().GetResult();Check(Data.Hash(target)==newHash,"legacy root launcher upgraded to exact verified receiver");string backup=Path.Combine(SelfUpdate.Home(root),"launcher-backups",oldHash+".exe");Check(File.Exists(backup)&&Data.Hash(backup)==oldHash,"exact previous launcher retained for rollback");SelfUpdate.RefreshLegacyLauncher(root).GetAwaiter().GetResult();Check(Data.Hash(target)==newHash,"migration idempotent");
 File.Copy(backup,target,true);Check(Data.Hash(target)==oldHash,"backup can restore original stable launcher");SelfUpdate.RefreshLegacyLauncher(root).GetAwaiter().GetResult();Check(Data.Hash(target)==newHash,"re-upgrade after rollback works");
 typeof(Cloud).GetMethod("Configure",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{null});byte[] bytes=Encoding.UTF8.GetBytes("fixture new MOD bytes");string hashFile=Path.Combine(root,"hash-fixture");File.WriteAllBytes(hashFile,bytes);string hash=Data.Hash(hashFile);File.Delete(hashFile);var downloads=new Downloads{bytes=bytes,manifest=new Manifest{version="test-only-after-exit"}};downloads.manifest.files.Add(new PackFile{path="BepInEx/plugins/test.dll",size=bytes.Length,sha256=hash,url=Channel.Web+"/releases/download/test/"+hash+".bin"});using(var transfer=new Transfer(downloads)){var result=new Engine(root,Engine.CheckGameStopped).Run(transfer,(s,p)=>{}).GetAwaiter().GetResult();Check(result.version=="test-only-after-exit"&&Data.Hash(Path.Combine(root,"BepInEx/plugins/test.dll"))==hash,"normal installation engine (fixture transport) still applies fixture update after game exits");result=new Engine(root,Engine.CheckGameStopped).Run(transfer,(s,p)=>{}).GetAwaiter().GetResult();Check(result.latest,"next normal check reports already current");}
 Check(File.ReadAllText(Path.Combine(root,"Lethal Company.exe"))=="fixture","game executable untouched");Console.WriteLine("RESULT "+count+" checks; "+root);
 }catch(Exception e){Console.Error.WriteLine(e);Environment.ExitCode=1;}}
}
